// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Alice locks in a guess at block 10
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // Move to block 12
        vm.roll(12);

        // Now settle: in P, guess was locked for block 11, so blockhash(11) is answer
        // In M, guess was locked for block 12, so blockhash(12) is answer
        // For block 11: assume blockhash(11) != bytes32(0) — we can still compare if it reverts
        // Actually, the ref will check block.number > guesses[msg.sender].block — yes, 12 > 11
        // Then answer = blockhash(11). Since guess = 0, if blockhash(11) != 0, guess != answer => no transfer
        // M: block.number > 12? 12 > 12 is false => require fails => revert
        // So difference: in P it succeeds (no transfer), in M it reverts
        address alice = address(0x1);
        vm.prank(alice);
        // Try to settle, catch revert
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // P: settle succeeds (no revert), M: settle reverts
        // So assertTrue(ok) passes on P, fails on M
        assertTrue(ok);
    }
}

