pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with initial 1 ether from deployment + 1 more ether for the guess
        vm.deal(address(c), 2 ether);

        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // Set block.number to 10
        vm.roll(10);

        // Alice locks in her guess at block 10
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(11))));

        // Warp to block 12 (block.number = 12)
        vm.roll(12);

        // Try to settle: reference succeeds (block 12 > 11), bug reverts (block 12 is NOT > 12)
        vm.prank(alice);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference passes (settles successfully), bug reverts
        // So we assertTrue on the reference behavior, which will fail on the bug
        assertTrue(ok);
    }
}

