pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 3 ether);
        vm.deal(address(0x1234), 2 ether);

        // Deploy with 1 ether
        vm.deal(address(this), 1 ether);
        c = new C(); 

        // Fund the contract with 2 ether for payout
        vm.deal(address(this), 2 ether);
        payable(address(c)).transfer(2 ether);

        // Alice locks in a guess at block 10
        vm.warp(10);
        vm.roll(10);
        vm.prank(address(0x1234));
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(11))));

        // Alice tries to settle at block 12
        vm.warp(12);
        vm.roll(12);
        bool ok;
        vm.prank(address(0x1234));
        try c.settle() { ok = true; } catch { ok = false; }

        // In reference, settlement succeeds; in bug, it reverts
        assertTrue(ok);
    }
}

