// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (already done in constructor)
        // Fund account with 1 ether to call lockInGuess
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.deal(address(this), 3 ether);
        // Send 1 ether to contract to fund constructor requirement (contract already has 1 from constructor)
        // Actually, constructor already has 1 ether from deployment, so total balance is 1 ether initially.
        // For settle to transfer 2 ether, the contract needs at least 2 ether.
        // Fund contract with an additional 1 ether via selfdestruct or direct transfer.
        // Simpler: use vm.deal on the contract address.
        vm.deal(address(c), 2 ether);
        // Warp to a block where the next block's blockhash will be bytes32(0)
        // By design, blockhash(block.number) is 0 for blocks more than 256 deep, but we can use vm.roll and vm.warp to control.
        // Actually, we can set the block number to a very high number so blockhash(block.number+1) is 0.
        // vm.roll sets block.number; blockhash(n) returns 0 for n >= block.number or n < block.number - 256.
        // So we can set block.number to 1, then lockInGuess sets guesses[msg.sender].block = 2.
        // Then we warp to block.number > 2, but we need blockhash(2) to be 0.
        // In Foundry, vm.roll does not change blockhash for future blocks. We can use vm.roll to set block.number to a high number so that blockhash(2) is 0.
        // Simplest: set block.number to 1000, then lockInGuess sets block to 1001. Then set block.number to 2000; blockhash(1001) will be 0 because it's more than 256 blocks ago.
        vm.roll(1000);
        // Call lockInGuess with a non-zero hash 
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(42)));
        // Now guess is bytes32(42) in reference, bytes32(0) in mutant.
        // Warp to a block where block.number > guesses[alice].block (which is 1001) and blockhash(1001) is 0.
        vm.roll(2000);
        // Now settle
        vm.prank(alice);
        c.settle();
        // In reference: stored hash = 42, blockhash(1001) = 0, so no match, no transfer => balance stays 2 ether.
        // In mutant: stored hash = 0, matches blockhash, transfer happens => balance becomes 0 ether.
        assertTrue(address(c).balance == 2 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with initial 1 ether (already done in constructor)
        // Provide additional ether for settlement
        vm.deal(address(this), 10 ether);
        vm.deal(address(c), 10 ether);

        // Prepare: set block.number so that next block's blockhash is bytes32(0)
        // We'll mine a block where blockhash will be zero (by ensuring block.number is large enough that blockhash returns 0)
        // Simpler: use vm.roll to a high number and then lockInGuess, but blockhash of a future block at current block.number+1 will be 0 because it's not in the last 256 blocks.
        // To guarantee blockhash(block.number+1) = 0, we roll to a block far ahead, then lockInGuess, then warp to block.number+2, then settle.
        vm.startPrank(address(0xdead));
        vm.deal(address(0xdead), 2 ether);

        // Roll to block 1000 so that blockhash(1001) is not available (returns 0)
        vm.roll(1000);

        // Call lockInGuess with some hash != bytes32(0)
        c.lockInGuess{value: 1 ether}(bytes32(uint256(42)));

        // Now move to block > guesses[msg.sender].block = 1001, so block.number > 1001
        vm.roll(1002);

        // Call settle
        c.settle();

        // In reference: stored hash = bytes32(uint256(42)), blockhash = 0, no match, no transfer => contract balance = 1 (initial) + 1 (lockInGuess) = 2
        // In buggy: stored hash = bytes32(0), blockhash = 0, match, transfer 2 => contract balance = 2 - 2 = 0
        assertTrue(address(c).balance == 2 ether, "Reference should have 2 ether, buggy would have 0");
    }
}

